using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
namespace CampaignDemo.Editor
{
    public static class FortLineVerification
    {
        static readonly List<string> results=new List<string>();
        static void Check(bool value,string name){if(!value)throw new Exception(name);results.Add("PASS "+name);}
        static void Near(float value,float expected,string name){Check(Mathf.Abs(value-expected)<.002f,name+" actual="+value);}
        static BattleUnit Unit(Transform root,string id,string player,UnitRole role,CampaignRuntime campaign,Vector3 p)
        {var g=new GameObject(id);g.transform.SetParent(root);g.transform.position=p;var u=g.AddComponent<BattleUnit>();u.unitId=id;u.ownerId=player;u.combatDefinition=ScriptableObject.CreateInstance<ArmyCombatDefinition>();u.combatDefinition.echelon=ArmyEchelon.Squad;u.combatDefinition.role=role;u.combatDefinition.visionRadius=3;u.combatDefinition.attackRadius=1;var road=g.AddComponent<ArmyRoadMover>();road.definition=ScriptableObject.CreateInstance<ArmyDefinition>();road.definition.speed=1;g.AddComponent<ArmyFreeMarchMover>().allowedTerrain=TerrainAccess.Ground|TerrainAccess.Road|TerrainAccess.Grass|TerrainAccess.Mountain;campaign.ConfigureUnit(u);u.Initialize();return u;}
        public static void Run(){try{FortLineInstaller.Configure();Validate();EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText("fort-line-verification.txt",e+"\n"+string.Join("\n",results));Debug.LogException(e);EditorApplication.Exit(1);}}
        public static void Validate()
        {
            results.Clear();var root=new GameObject("Line fort test");var world=root.AddComponent<BattleWorld>();world.enabled=false;world.players=new[]{"A","B"};world.currentPlayer="A";world.fogEnabled=false;world.points=new RecoveryPoint[0];var campaign=root.AddComponent<CampaignRuntime>();campaign.enabled=false;campaign.world=world;campaign.rules=ScriptableObject.CreateInstance<CampaignRules>();campaign.rules.troopStrength=new[]{100f};campaign.combined=root.AddComponent<CombinedArmsWorld>();campaign.combined.enabled=false;campaign.combined.world=world;campaign.combined.engineering=ScriptableObject.CreateInstance<EngineeringDefinition>();campaign.logistics=root.AddComponent<LogisticsWorld>();campaign.logistics.enabled=false;campaign.logistics.world=world;campaign.Bind();world.campaign=campaign;
            var mapObj=new GameObject("map");mapObj.transform.SetParent(root.transform);var map=mapObj.AddComponent<FreeMarchMapRuntime>();map.definition=ScriptableObject.CreateInstance<FreeMarchMapDefinition>();map.definition.bounds=new Rect(-10,-10,20,20);var setup=root.AddComponent<RoadMarchSceneSetup>();setup.freeMarchMap=map;world.setup=setup;
            var engineer=Unit(root.transform,"engineer","A",UnitRole.Engineer,campaign,Vector3.zero);var soldier=Unit(root.transform,"soldier","B",UnitRole.Infantry,campaign,new Vector3(0,1));world.units=new[]{engineer,soldier};world.Initialize();
            var nearObj=new GameObject("near city");nearObj.transform.SetParent(root.transform);nearObj.transform.position=new Vector3(-2,0);var near=nearObj.AddComponent<RecoveryPoint>();near.pointId="near";near.ownerId="A";near.resourceStock=1000;var farObj=new GameObject("far city");farObj.transform.SetParent(root.transform);farObj.transform.position=new Vector3(5,0);var far=farObj.AddComponent<RecoveryPoint>();far.ownerId="A";far.resourceStock=10000;world.points=new[]{far,near};
            var points=new[]{new Vector3(-.5f,1),new Vector3(.5f,1)};var works=campaign.lineWorks;var r=works.Rules;r.metersPerWorldUnit=10;r.lineCostPerMeter=2;r.lineBuildSecondsPerMeter=1;r.lineDismantleSecondsPerMeter=1;
            Near(FortificationLineWorks.Length(points),1,"polyline world length");var clamp=FortificationLineWorks.ClampToVision(engineer,Vector3.zero,new Vector3(10,0));Near(clamp.x,3,"cursor clamps exactly to vision boundary");
            Check(works.CanBuild(engineer,points,out _),"line build allowed within visibility");near.resourceStock=10;Check(!works.Build(engineer,points).accepted&&far.resourceStock==10000,"insufficient nearest city does not charge farther rich city");near.resourceStock=1000;Check(works.Build(engineer,points).accepted,"begin whole line construction");Near(near.resourceStock,980,"whole length cost charged to nearest city");Near(works.Remaining(engineer),10,"build duration proportional to length");Check(campaign.combined.fortifications.Count==0,"no partial independent fort segments before completion");works.Tick(4);works.Cancel(engineer);Near(near.resourceStock,992,"cancel refunds only unfinished fraction");Check(!engineer.Working&&campaign.combined.fortifications.Count==0,"cancel clears project without spawning partial line");
            Check(works.CanBuild(engineer,new[]{new Vector3(0,1),new Vector3(1,1),new Vector3(.5f,2)},out _),"sharp nonoverlapping bends remain allowed");Check(works.CanBuild(engineer,new[]{new Vector3(-.5f,1),new Vector3(.5f,2),new Vector3(-.5f,2),new Vector3(.5f,1)},out _),"crossing line drawing allowed");Check(works.CanBuild(engineer,new[]{new Vector3(-.5f,1),new Vector3(.5f,1),new Vector3(-.5f,1)},out _),"overlapping sections allowed with full length cost");
            Check(works.Build(engineer,points).accepted,"restart construction");works.Tick(10);Check(campaign.combined.fortifications.Count==1,"one stroke produces one fortification");var line=campaign.combined.fortifications[0];Check(line.IsLine&&line.linePoints.Length==2,"whole polyline geometry retained");Near(line.builtLengthMeters,10,"physical length retained");Near(line.Health,10*r.lineHealthPerMeter,"health proportional to length");Check(works.CanBuild(engineer,points,out _),"new line may overlap an existing line");Check(works.CanBuild(engineer,new[]{points[1],new Vector3(1.5f,1)},out _),"new line may connect at existing endpoint");Check(line.engineerSide==Vector3.zero,"visual orientation snapshots engineer position");Near(line.DistanceTo(new Vector3(.4f,1.1f)),.1f,"distance evaluated along line rather than only first anchor");Check(line.Crosses(new Vector3(.4f,0),new Vector3(.4f,2)),"movement crosses far section");Check(!line.Crosses(new Vector3(4,0),new Vector3(4,2)),"unrelated movement not slowed");
            Check(works.Dismantle(soldier,line).accepted,"opponent can dismantle entire line");Near(works.Remaining(soldier),10,"ordinary dismantle duration proportional to length");works.Tick(5);Check(!line.Destroyed,"half dismantling does not remove half line");works.Cancel(soldier);Check(!line.Destroyed,"cancel leaves entire existing line");Check(works.Dismantle(engineer,line).accepted,"owner engineer may dismantle line");Near(works.Remaining(engineer),2,"engineer faster independent of low ordinary damage");works.Tick(2);Check(line.Destroyed,"completion removes entire construction");
            var second=works.CreateLine(new[]{new Vector3(-2,2),new Vector3(2,2)},Vector3.zero,"A",0,40);engineer.transform.position=new Vector3(0,1);engineer.combatDefinition.attackRadius=.8f;Check(campaign.ProtectingFort(engineer)==second,"attack radius intersection activates friendly fort buff");engineer.combatDefinition.attackRadius=.2f;Check(campaign.ProtectingFort(engineer)==null,"outside attack radius gets no buff");engineer.combatDefinition.attackRadius=2;var higher=works.CreateLine(new[]{new Vector3(-2,2.5f),new Vector3(2,2.5f)},Vector3.zero,"A",1,40);Check(campaign.ProtectingFort(engineer)==higher,"multiple fortifications choose highest bonus rather than stack");Check(campaign.CoveringFort(engineer)==null,"distant buff does not become physical artillery cover");
            foreach(var f in campaign.combined.fortifications)f.Demolish();engineer.transform.position=Vector3.zero;soldier.transform.position=new Vector3(.5f,0);soldier.combatDefinition.role=UnitRole.Scout;engineer.Initialize();soldier.Initialize();float before=soldier.Personnel;CampaignCombatSolver.Resolve(campaign,1);Near(before-soldier.Personnel,campaign.rules.lossPerStrengthPerSecond*100*campaign.rules.engineerOrdinaryAttackMultiplier,"engineer ordinary fire uses independent low multiplier");
            foreach(UnitRole role in Enum.GetValues(typeof(UnitRole)))foreach(var kind in new[]{TerrainKind.Grass,TerrainKind.Mountain,TerrainKind.HighMountain,TerrainKind.Water})
            {float retained=FortLineInstaller.Retained(role,kind);bool access=(FortLineInstaller.Access(role)&(TerrainAccess)(1<<(int)kind))!=0;Check(access==(retained>0),"terrain permission matches retained speed "+role+" "+kind);}
            Near(FortLineInstaller.Retained(UnitRole.Infantry,TerrainKind.Grass),.9f,"infantry grass retains 90 percent");Near(FortLineInstaller.Retained(UnitRole.Tank,TerrainKind.Grass),.6f,"tank grass retains 60 percent");Near(FortLineInstaller.Retained(UnitRole.PersonnelCarrier,TerrainKind.Grass),.3f,"carrier grass retains 30 percent");Near(FortLineInstaller.Retained(UnitRole.Infantry,TerrainKind.Mountain),.4f,"infantry mountain retains 40 percent");Near(FortLineInstaller.Retained(UnitRole.MountainInfantry,TerrainKind.Mountain),.7f,"mountain infantry retains 70 percent");Near(FortLineInstaller.Retained(UnitRole.Artillery,TerrainKind.Mountain),.2f,"artillery follows tank mountain 20 percent");
            foreach(var f in campaign.combined.fortifications)if(f!=null)UnityEngine.Object.DestroyImmediate(f.gameObject);UnityEngine.Object.DestroyImmediate(root);File.WriteAllText("fort-line-verification.txt",results.Count+" checks passed\n"+string.Join("\n",results));Debug.Log("FORT_LINE_VERIFY_PASS "+results.Count);
        }
    }
}


